func TestBuiltinConstructorsParity(t *testing.T) {
	cases := []struct {
		name string
		ctor func(string) Sensitive[string]
		fn   func(string) string
		in   string
	}{
		{"NewPhone", NewPhone, Mobile, "0987654321"},
